import{z as p,x as m,o as i,c as d,q as o,j as E,D as t,d as e,s as l,S as n,b as r}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"Word2Vec skip-gram","description":"","frontmatter":{"title":"Word2Vec skip-gram","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/word2vec-skipgram.md","filePath":"llm/word2vec-skipgram.md","lastUpdated":1791063341000}'),A={name:"llm/word2vec-skipgram.md"};function c(h,a,B,k,_,D){const s=m("Mermaid");return i(),d("div",null,[a[2]||(a[2]=o('<h1 id="word2vec-skip-gram" tabindex="-1">Word2Vec skip-gram <a class="header-anchor" href="#word2vec-skip-gram" aria-label="Permalink to &quot;Word2Vec skip-gram&quot;">​</a></h1><div class="epigraph"><p>固定中心词，去预测窗口里每一个上下文词；两张查找表把分布假设收成可反向的分类目标。</p><footer>—— 据 Mikolov et al., Efficient Estimation of Word Representations in Vector Space, 2013；Mikolov et al., Distributed Representations of Words and Phrases, NeurIPS 2013 整理</footer></div><p><a href="/llm/distributional-hypothesis">词向量与分布假设</a>给出「邻域 \\(\\Rightarrow\\) 靠近」。本课不重写 Firth。缺口是：把邻域写成显式的预测问题，使交叉熵能训练向量。skip-gram 选中心词 \\(w\\)，对窗口内每个上下文 \\(c\\) 最大化 \\(P(c\\mid w)\\)。CBOW 方向相反，本课不并行展开。负采样是下一课，因为整表 softmax 的 \\(|V|\\) 还太大。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分布假设没有指定似然。共现矩阵加 SVD 能给出向量，但接不进上一单元的小批量 SGD，也难与非线性层共用。缺口是一个神经网络式目标：输入是一个词的向量，输出是词表上的分布，标签是窗口里的词。这样，<a href="/llm/clm-as-next-token">下一词分类</a>的代数可以直接用，只是条件从「左侧整句」收成「中心词」，上下文从「未来一个符号」换成「窗口内各个符号」。</p><p>skip-gram 把每个 \\((w,c)\\) 对当成独立分类。窗口大小 \\(k\\) 是超参：\\(k\\) 大则主题相近也算正例，\\(k\\) 小则更句法。本课不调 \\(k\\)，只承认目标随窗口定义而变。位置在窗口内通常不加权或仅按距离降权；真正的位置编码还不存在——那是本课程最后一课的缺口。</p><p><span class="marginnote">数字实例：句子「the cat sat on the mat」，取窗口 \\(k=2\\)、中心词 sat，正例对是 sat→the、sat→cat、sat→on、sat→the 共 4 对；窗口滑到下一个词又生成一批。10 亿词的语料按 \\(k=2\\) 大约产生 40 亿个训练对。</span></p><h3 id="skip-gram-不是语言模型" tabindex="-1">skip-gram 不是语言模型 <a class="header-anchor" href="#skip-gram-不是语言模型" aria-label="Permalink to &quot;skip-gram 不是语言模型&quot;">​</a></h3><p>语言模型要 \\(P(t_i\\mid t_{\\lt i})\\)，必须读有序前缀。skip-gram 丢掉次序，只保留「是否同窗」。它学到的是词型的静态向量，不是上下文相关的 token 表示。用 skip-gram 向量初始化嵌入表可以，把它当成已经解决语言建模，后课 RNN 与注意力会没有事做。本课的输出是 \\(|V|\\) 行向量，一行一词型。</p><p><span class="marginnote">「词型」是词典条目（如 run），与出现位置无关；「词例」才是句子里某一次出现。skip-gram 学的是词型向量：run 的所有出现共享同一行，于是「跑步」和「经营」两种含义被平均进同一个向量——这正是静态向量的根本局限。</span></p><p><span class="marginnote">实现上有两张表：中心词 \\(U\\in\\mathbb{R}^{|V|\\times d}\\)，上下文 \\(V\\in\\mathbb{R}^{|V|\\times d}\\)。打分 \\(u_w^\\top v_c\\)。训练结束后常只用 \\(U\\)，或用 \\(U+V\\)。两张表是为了让同一词在作中心与作上下文时角色分开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对语料位置 \\(t\\)，中心 \\(w=t_t\\)，上下文 \\(c\\in\\{t_{t-k},\\ldots,t_{t+k}\\}\\setminus\\{w\\}\\)。logits 为与所有词型的点积 \\(U_w V^\\top\\in\\mathbb{R}^{|V|}\\)，再稳定 softmax，损失是 \\(-\\log p[c]\\)。每个窗口对多个 \\(c\\) 求和。这正是全词表交叉熵，计算量每步 \\(O(|V|d)\\)，大词表上不可接受——下一课改目标。本课先把「正确的、但太贵的」似然写清，避免负采样看起来像凭空而来的技巧。</p><p><span class="marginnote">直觉类比：全词表 softmax 像每次点名都让全校 5 万人都应答一遍，只为确认一人到没到。\\(|V|=50000\\)、\\(d=300\\) 时一步要算 \\(1.5\\times 10^7\\) 次乘加——这正是下一课负采样要砍掉的账单。</span></p>',14)),(i(),E(n,null,{default:t(()=>[l(s,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E4%B8%AD%E5%BF%83%E8%AF%8D%22%5D%20--%3E%20U%5B%22%E6%9F%A5%E8%A1%A8%20U%22%5D%0A%20%20U%20--%3E%20DOT%5B%22%E4%B8%8E%E5%85%A8%E4%BD%93%E4%B8%8A%E4%B8%8B%E6%96%87%E5%90%91%E9%87%8F%E7%82%B9%E7%A7%AF%22%5D%0A%20%20VTAB%5B%22%E8%A1%A8%20V%22%5D%20--%3E%20DOT%0A%20%20DOT%20--%3E%20SM%5B%22%E8%AF%8D%E8%A1%A8%E4%B8%8A%20softmax%22%5D%0A%20%20C%5B%22%E7%AA%97%E5%8F%A3%E5%86%85%E7%9A%84%20c%22%5D%20--%3E%20CE%5B%22%E4%BA%A4%E5%8F%89%E7%86%B5%22%5D%0A%20%20SM%20--%3E%20CE%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("梯度把 \\(u_w\\) 拉向 \\(v_c\\)，并把 \\(u_w\\) 从其他 \\(v_{c'}\\) 推开（按 \\(p_{c'}\\) 加权）。高频词作为 \\(c\\) 时贡献大，这与分布假设一致：常见邻域主导几何。低频词更新稀，向量靠近初始化。子词课将用更短单位来分享这些更新。点积打分沿用"),r("a",{href:"/llm/norm-cosine-projection"},"范数、余弦与投影"),e("：未归一的内积含长度，高频词向量往往更长。")],-1)),(i(),E(n,null,{default:t(()=>[l(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20UW%5B%22%E4%B8%AD%E5%BF%83%E8%AF%8D%E5%90%91%E9%87%8F%20u_w%22%5D%20--%3E%20PULL%5B%22%E6%8B%89%E5%90%91%3A%20%E7%AA%97%E5%8F%A3%E5%86%85%E6%AF%8F%E4%B8%AA%20c%20%E7%9A%84%20v_c%22%5D%0A%20%20UW%20--%3E%20PUSH%5B%22%E6%8E%A8%E5%BC%80%3A%20%E5%BD%93%E5%89%8D%E9%AB%98%E6%A6%82%E7%8E%87%E7%9A%84%E9%94%99%E8%AF%AF%E5%80%99%E9%80%89%22%5D%0A%20%20PULL%20--%3E%20GEO%5B%22%E5%85%B1%E7%8E%B0%E8%AF%8D%E5%9C%A8%E7%A9%BA%E9%97%B4%E4%B8%AD%E8%81%9A%E7%B0%87%22%5D%0A%20%20PUSH%20--%3E%20LEN%5B%22%E9%AB%98%E9%A2%91%E8%AF%8D%E5%90%91%E9%87%8F%E5%81%8F%E9%95%BF%22%5D%0A%20%20GEO%20--%3E%20OUT%5B%22%E4%BA%A7%E5%87%BA%3A%20%E9%9D%99%E6%80%81%E8%AF%8D%E5%9E%8B%E5%90%91%E9%87%8F%E8%A1%A8%22%5D%0A%20%20LEN%20--%3E%20OUT%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p>因为丢掉词序，skip-gram 不能区分「狗咬人」与「人咬狗」的角色，只能说这些词型曾共现。要顺序与长程，必须把条件改回序列模型。本课停在词型几何。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入负采样、层次 softmax 的细节。下一课<a href="/llm/negative-sampling">负采样</a>把 \\(|V|\\) 项归一化换成几个二分类。后课默认：说到 Word2Vec，默认 skip-gram 的「中心预测窗口」；它不是自回归语言模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>skip-gram 用中心词向量预测窗口内上下文，目标是词表上的 softmax 交叉熵。</li><li>两张表 \\(U,V\\) 分开中心与上下文角色。</li><li>每步 \\(O(|V|d)\\)，大词表上需要下一课的近似。</li><li>学到的是静态词型向量，不含词序。</li><li>出处：Mikolov et al., 2013；NeurIPS 2013。</li></ul>',5))])}const u=p(A,[["render",c]]);export{g as __pageData,u as default};
